      "urgencia": "MEDIA",
      "titulo": "SHCP actualiza Sistema de Alertas de Deuda: Nuevo León, Chihuahua y Coahuila en observación preventiva",
      "bajada": "Las tasas de interés reales y el costo financiero presionan los techos de endeudamiento. Cinco estados destinan más del 65% de sus participaciones al servicio de pasivos bancarios.",
      "cuerpo": "La Unidad de Coordinación con Entidades Federativas de la SHCP publicó la actualización trimestral del Sistema de Alertas de la Deuda Pública Subnacional. Aunque la mayoría de las 32 entidades se mantienen en semáforo verde (endeudamiento sostenible), los estados de Nuevo León, Chihuahua, Coahuila y Durango permanecen en rango amarillo (en observación). Para Nuevo León, el costo del servicio de deuda superó los $9,800 mdp en 2025, derivado de financiamientos para las nuevas líneas del metro y obras hídricas. El límite de endeudamiento adicional para estados en semáforo amarillo queda topado legalmente al 5% de sus ingresos de libre disposición.",
