      "fecha": "19 de Enero, 2026",
      "hora": "11:00 CST",
      "urgencia": "MEDIA",
      "titulo": "La paradoja municipal: recaudan apenas 0.16% del PIB en predial frente al 1.0% de la OCDE",
      "bajada": "Alcaldes evitan actualizar catastros por costo político electoral, refugiándose en transferencias del FORTAMUN y Ramo 28 sin rendir cuentas a sus ciudadanos.",
      "cuerpo": "Un informe conjunto entre el IMCO y la OCDE expuso la debilidad estructural de los municipios mexicanos. A pesar de tener la facultad exclusiva de cobrar el impuesto predial desde la reforma al Artículo 115 constitucional en 1983, solo 80 municipios de los 2,477 concentran el 75% de toda la recaudación inmobiliaria del país. Municipios turísticos y metropolitanos como San Pedro Garza García, Zapopan, Benito Juárez (CDMX) y Corregidora demuestran que la modernización catastral satelital puede quintuplicar los ingresos propios y romper la sumisión política frente a los gobernadores.",
