      "titulo": "Listado 69-B: Detectan red de 142 empresas fantasmas en contratos de salud de 6 gobiernos estatales",
      "bajada": "La Fiscalía Especializada en Combate a la Corrupción abre carpetas de investigación por triangulación de recursos etiquetados del Ramo 33 para adquisición de medicamentos inexistentes.",
      "cuerpo": "El Servicio de Administración Tributaria (SAT) notificó en el Diario Oficial de la Federación una nueva lista definitiva de Empresas que Facturan Operaciones Simuladas (EFOS). De acuerdo con el cruce de datos con la Plataforma Nacional de Transparencia, 142 de estas razones sociales ficticias fungieron como proveedoras de insumos médicos, batas quirúrgicas y reactivos de laboratorio en los sistemas estatales de salud de Veracruz, Estado de México, Michoacán y Chiapas entre 2022 y 2024. Los domicilios fiscales registrados corresponden a lotes baldíos, tienditas de abarrotes o viviendas abandonadas.",
