            "veredicto_civico": "Mientras Porfirio Díaz alcanzó el primer superávit fiscal moderno (+0.8%) y consolidó crédito de primera categoría con Limantour, Santa Anna representó el extremo del colapso hacendario: moratorias continuas de la deuda externa, aduanas hipotecadas a prestamistas privados y bancarrota estructural del Estado mexicano."
