            "retroceso": "La insolvencia extrema del erario en 1861 lo obligó a decretar la suspensión de pagos por dos años de la deuda externa, lo que detonó el desembarco de la Alianza Tripartita (Inglaterra, España y Francia) y el régimen invasor del Segundo Imperio; recursos públicos absorbidos casi en su totalidad por la resistencia bélica.",
            "veredicto_civico": "Juárez salvaguardó la independencia y la dignidad republicana gobernando con las arcas vacías desde su carruaje itinerante; su general en el Sitio de Puebla, Don Porfirio Díaz, capitalizó la estabilidad política heredada de la República Restaurada para transformar esa austeridad en la mayor red ferroviaria y financiera del país."
